class TestHelpers:
    """Collection of static helper methods for test assertions and utilities."""
    
    @staticmethod
    def assert_code_safety(code: str) -> None:
        """
        Validate that generated code passes safety checks.
        
        Args:
            code: Python code string to validate
            
        Raises:
            AssertionError: If code contains unsafe patterns
        """
        unsafe_patterns = [
            "__import__",
            "eval(",
            "exec(",
            "compile(",
            "os.system",
            "subprocess.call",
            "shutil.rmtree",
            "globals()",
            "locals()",
        ]
        
        for pattern in unsafe_patterns:
            assert pattern not in code, f"Unsafe pattern detected: {pattern}"
    
    @staticmethod
    def assert_valid_python_syntax(code: str) -> None:
        """
        Verify that code string is valid Python syntax.
        
        Args:
            code: Python code string to validate
            
        Raises:
            AssertionError: If code has syntax errors
        """
        try:
            compile(code, '<test>', 'exec')
        except SyntaxError as e:
            raise AssertionError(f"Invalid Python syntax: {e}")
    
    @staticmethod
    def generate_test_file(
        content: str,
        filename: str,
        directory: Optional[Path] = None
    ) -> Path:
        """
        Create a temporary test file with given content.
        
        Args:
            content: File content
            filename: Name of the file
            directory: Optional directory (defaults to TEST_DATA_DIR)
            
        Returns:
            Path to created file
        """
        target_dir = directory or TEST_CONFIG.TEST_DATA_DIR
        target_dir.mkdir(parents=True, exist_ok=True)
        
        file_path = target_dir / filename
        file_path.write_text(content, encoding='utf-8')
        
        test_logger.debug(f"Created test file: {file_path}")
        return file_path
    
    @staticmethod
    def measure_execution_time(func: Callable, *args, **kwargs) -> float:
        """
        Measure execution time of a function in milliseconds.
        
        Args:
            func: Function to measure
            *args: Function arguments
            **kwargs: Function keyword arguments
            
        Returns:
            Execution time in milliseconds
        """
        import time
        start = time.perf_counter()
        func(*args, **kwargs)
        end = time.perf_counter()
        return (end - start) * 1000


